ents":{"kcal":364,"protein":18.8,"carbs":37.9,"fat":15.2,"fiber":9.6,"sodium":437,"calcium":437,"iron":2.1,"potassium":691,"magnesium":42,"vitamin_c":41.4},"portions":[],"composition":{"dataset":"sara2-2022-v1","source_sha256":"14706a46e0262e2223b0c44d4c77c31090e3554cf63602fe58ab765f32b81c7f","record_id":"SARA2-2022-P137-T26.A-R18","basis":{"amount":100,"unit":"g"},"carbohydrates":"available","source_page":137}}},{"id":"153b6f53-9016-502d-9ab2-0e4047f0f739","payload":{"name":"Herbalife- Batido nutricional proteico. Formula 1 (gramo)","brand":"","category":"Suplementos nutricionales","kind":"supplement","source":"SARA 2 · Ministerio de Salud · 2022","reference":"https://iah.msal.gov.ar/doc/720.pdf · p. 137 · tabla 26.A · fila 19 · ID derivado, no oficial","nutrients":{"kcal":392,"protein":53.6,"carbs":20.4,"fat":10.7,"fiber":0,"sodium":1214,"calcium":714,"iron":22.5,"potassium":1000,"magnesium":500,"vitamin_c":75},"portions":[],"composition":{"dataset":"sara2-2022-v1","source_sha256":"14706a46e0262e2223b0c44d4c77c31090e3554cf63602fe58ab765f32b81c7f","record_id":"SARA2-2022-P137-T26.A-R19","basis":{"amount":100,"unit":"g"},"carbohydrates":"available","source_page":137}}},{"id":"e7bdaf41-b2cd-53ff-be2f-d76db928efca","payload":{"name":"Herbalife-Batido de cookies y cream. Formula 1 (gramo)","brand":"","category":"Suplementos nutricionales","kind":"supplement","source":"SARA 2 · Ministerio de Salud · 2022","reference":"https://iah.msal.gov.ar/doc/720.pdf · p. 137 · tabla 26.A · fila 20 · ID derivado, no oficial","nutrients":{"kcal":392,"protein":53.6,"carbs":20.4,"fat":10.7,"fiber":0,"sodium":1214,"calcium":714,"iron":22.5,"potassium":1000,"magnesium":500,"vitamin_c":75},"portions":[],"composition":{"dataset":"sara2-2022-v1","source_sha256":"14706a46e0262e2223b0c44d4c77c31090e3554cf63602fe58ab765f32b81c7f","record_id":"SARA2-2022-P137-T26.A-R20","basis":{"amount":100,"unit":"g"},"carbohydrates":"available","source_page":137}}},{"id":"64d28d13-9ea7-5a54-95e7-d7acfddf7f8c","payload":{"name":"Supportan drink (mililitro)","brand":"","category":"Suplementos nutricionales","kind":"supplement","source":"SARA 2 · Ministerio de Salud · 2022","reference":"https://iah.msal.gov.ar/doc/720.pdf · p. 139 · tabla 26.A · fila 1 · ID derivado, no oficial","nutrients":{"kcal":150,"protein":10,"carbs":12.4,"fat":6.7,"fiber":1.5,"sodium":47,"calcium":203,"iron":2.5,"potassium":129,"magnesium":26,"vitamin_c":18.8},"portions":[],"composition":{"dataset":"sara2-2022-v1","source_sha256":"14706a46e0262e2223b0c44d4c77c31090e3554cf63602fe58ab765f32b81c7f","record_id":"SARA2-2022-P139-T26.A-R1","basis":{"amount":100,"unit":"ml"},"carbohydrates":"available","source_page":139}}},{"id":"bca346d5-7c97-54bd-a134-6cc4fc92a6a3","payload":{"name":"Herbalife- Polvo de proteínas personalizado. Fórmula 3 (gramo)","brand":"","category":"Suplementos nutricionales","kind":"supplement","source":"SARA 2 · Ministerio de Salud · 2022","reference":"https://iah.msal.gov.ar/doc/720.pdf · p. 139 · tabla 26.A · fila 2 · ID derivado, no oficial","nutrients":{"kcal":360,"protein":90,"carbs":0,"fat":0,"fiber":0,"sodium":0,"calcium":0,"iron":0,"potassium":0,"magnesium":0,"vitamin_c":0},"portions":[],"composition":{"dataset":"sara2-2022-v1","source_sha256":"14706a46e0262e2223b0c44d4c77c31090e3554cf63602fe58ab765f32b81c7f","record_id":"SARA2-2022-P139-T26.A-R2","basis":{"amount":100,"unit":"g"},"carbohydrates":"available","source_page":139}}},{"id":"e993bf7c-8915-5499-9d37-d5aec9e360a6","payload":{"name":"Whey Pro. Classic Line (gramo)","brand":"","category":"Suplementos nutricionales","kind":"supplement","source":"SARA 2 · Ministerio de Salud · 2022","reference":"https://iah.msal.gov.ar/doc/720.pdf · p. 139 · tabla 26.A · fila 3 · ID derivado, no oficial","nutrients":{"kcal":359,"protein":80,"carbs":0,"fat":4.3,"fiber":0,"sodium":0,"calcium":0,"iron":0,"potassium":0,"magnesium":0,"vitamin_c":0},"portions":[],"composition":{"dataset":"sara2-2022-v1","source_sha256":"14706a46e0262e2223b0c44d4c77c31090e3554cf63602fe58ab765f32b81c7f","record_id":"SARA2-2022-P139-T26.A-R3","basis":{"amount":100,"unit":"g"},"carbohydrates":"available","source_page":139}}},{"id":"46f344d6-ef0c-566a-8f06-2fd24f830f96","payload":{"name":"Levadura de cerveza (gramo)","brand":"","category":"Suplementos nutricionales","kind":"supplement","source":"SARA 2 · Ministerio de Salud · 2022","reference":"https://iah.msal.gov.ar/doc/720.pdf · p. 139 · tabla 26.A · fila 4 · ID derivado, no oficial","nutrients":{"kcal":288,"protein":40.4,"carbs":14.3,"fat":7.6,"fiber":26.9,"sodium":51,"calcium":30,"iron":2.17,"potassium":955,"magnesium":54,"vitamin_c":0.3},"portions":[],"composition":{"dataset":"sara2-2022-v1","source_sha256":"14706a46e0262e2223b0c44d4c77c31090e3554cf63602fe58ab765f32b81c7f","record_id":"SARA2-2022-P139-T26.A-R4","basis":{"amount":100,"unit":"g"},"carbohydrates":"available","source_page":139}}}]'::jsonb) loop
  select * into existing from public.food_catalog where id=(item->>'id')::uuid for update;
  if found then
   if existing.owner_id is not null or existing.revision<>1 or existing.payload is distinct from item->'payload' then
    raise exception using errcode='23505',message='sara2_seed_collision';
   end if;
  else
   insert into public.food_catalog(id,owner_id,revision,payload,updated_at) values((item->>'id')::uuid,null,1,item->'payload','2022-07-01T00:00:00Z');
  end if;
 end loop;
end;$sara2$;
-- SARA2_SEED_END
create or replace function public.save_recipe_draft(payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare
  nid uuid; rid uuid; prior public.recipe_versions; live public.food_catalog;
  clean jsonb; item jsonb; ref jsonb; food jsonb; measure jsonb; entry jsonb;
  frozen_lines jsonb := '[]'; clean_items jsonb := '[]'; totals jsonb := '{}'; per_portion jsonb := '{}'; per100 jsonb := '{}';
  snapshot jsonb; result jsonb; card jsonb; macros jsonb; derived_nutrition jsonb; old_snapshot jsonb;
  native_quantity numeric; native_unit text; grams numeric; weight numeric := 0; total numeric; portions numeric; final_weight numeric; cooking integer;
  key text; label text; labels text[] := '{}'; has_catalog boolean := false; unknown_weight boolean := false;
  ai_source text; source text; vid uuid;
begin
  nid:=public.recipe_assert_nutri(); rid:=(payload->>'id')::uuid;
  perform pg_advisory_xact_lock(hashtextextended(rid::text,4));
  perform pg_advisory_xact_lock(hashtextextended(rid::text,0));
  if exists(select 1 from public.recipes r where r.id=rid and r.nutritionist_id<>nid) then raise exception using errcode='42501',message='recipe_owner'; end if;
  select * into prior from public.recipe_versions where recipe_id=rid order by version desc limit 1;
  old_snapshot:=prior.catalog_recipe;
  has_catalog:=old_snapshot is not null;
  if payload ? 'final_weight_g' and payload->'final_weight_g'<>'null'::jsonb then
    if jsonb_typeof(payload->'final_weight_g')<>'number' then raise exception using errcode='22023',message='recipe_weight'; end if;
    final_weight:=(payload->>'final_weight_g')::numeric;
    if final_weight<=0 or final_weight>100000 then raise exception using errcode='22023',message='recipe_weight'; end if;
  end if;
  if payload ? 'cooking_minutes' and payload->'cooking_minutes'<>'null'::jsonb then
    if jsonb_typeof(payload->'cooking_minutes')<>'number' or (payload->>'cooking_minutes')::numeric<>trunc((payload->>'cooking_minutes')::numeric) then raise exception using errcode='22023',message='recipe_cooking'; end if;
    cooking:=(payload->>'cooking_minutes')::integer;
    if cooking<0 or cooking>1440 then raise exception using errcode='22023',message='recipe_cooking'; end if;
  end if;
  clean:=payload-'final_weight_g'-'cooking_minutes';
  if jsonb_typeof(payload->'items') is distinct from 'array' then raise exception using errcode='22023',message='recipe_items'; end if;
  perform public.recipe_validate_draft(jsonb_set(clean-'expected_revision'-'card','{items}',
    coalesce((select jsonb_agg(value-'catalog_ref') from jsonb_array_elements(payload->'items')),'[]'::jsonb)));
  for item in select value from jsonb_array_elements(payload->'items') loop
    label:=public.recipe_normalize_name(item->>'name');
    if label=any(labels) then raise exception using errcode='22023',message='recipe_duplicate'; end if;
    labels:=array_append(labels,label); food:=null; grams:=null; native_quantity:=null;
    if item ? 'catalog_ref' then
      has_catalog:=true; ref:=item->'catalog_ref';
      if jsonb_typeof(ref) is distinct from 'object' or not(ref ?& array['id','revision','measure']) or
        (select count(*) from jsonb_object_keys(ref))<>3 or jsonb_typeof(ref->'id') is distinct from 'string' or
        jsonb_typeof(ref->'revision') is distinct from 'number' or (ref->>'revision')::numeric<>trunc((ref->>'revision')::numeric) or
        (ref->>'revision')::numeric not between 1 and 9007199254740991 or
        (ref->'measure'<>'null'::jsonb and (jsonb_typeof(ref->'measure')<>'string' or length(ref->>'measure') not between 1 and 80)) then
        raise exception using errcode='22023',message='recipe_food_ref';
      end if;
      select value->'food' into food from jsonb_array_elements(coalesce(old_snapshot->'lines','[]'::jsonb))
        where value->'food'->>'id'=ref->>'id' and value->'food'->>'revision'=ref->>'revision' limit 1;
      if food is null then
        select * into live from public.food_catalog where id=(ref->>'id')::uuid and (owner_id is null or owner_id=nid) for share;
        if not found then raise exception using errcode='42501',message='recipe_food_owner'; end if;
        if live.revision<>(ref->>'revision')::bigint then raise exception using errcode='PT409',message='recipe_food_changed'; end if;
        food:=live.payload||jsonb_build_object('id',live.id,'revision',live.revision,'owner_id',live.owner_id,'updated_at',live.updated_at);
      end if;
      native_unit:=coalesce(food#>>'{composition,basis,unit}','g');
      if food ? 'composition' and ref->'measure'='null'::jsonb and item->>'unit'<>native_unit then raise exception using errcode='22023',message='recipe_native_unit'; end if;
      grams:=(item->>'quantity')::numeric;
      if ref->'measure'<>'null'::jsonb then
        select value into measure from jsonb_array_elements(food->'portions') where value->>'name'=ref->>'measure';
        if measure is null then raise exception using errcode='22023',message='recipe_measure'; end if;
        grams:=grams*(measure->>'grams')::numeric;
      end if;
      if grams<=0 or grams>100000 then raise exception using errcode='22023',message='recipe_grams'; end if;
      native_quantity:=grams;
      clean_items:=clean_items||jsonb_build_array((item-'catalog_ref')||jsonb_build_object('quantity',native_quantity,'unit',native_unit));
      if native_unit='ml' then grams:=null; end if;
    else
      if item->>'unit'='g' then grams:=(item->>'quantity')::numeric; end if;
      clean_items:=clean_items||jsonb_build_array(item);
    end if;
    if grams is null then unknown_weight:=true; else weight:=weight+grams; end if;
    frozen_lines:=frozen_lines||jsonb_build_array(item||jsonb_build_object('grams',grams,'native_quantity',native_quantity,'food',food));
  end loop;
  clean:=jsonb_set(clean,'{items}',clean_items);
  -- Validates every remaining field, including arbitrary extra item keys.
  perform public.recipe_validate_draft(clean-'expected_revision'-'card');
  if payload ? 'card' then perform public.recipe_validate_card(payload->'card'); end if;
  if has_catalog then
    portions:=(payload->>'yield_portions')::numeric;
    ai_source:=coalesce(old_snapshot->>'estimate_source',case when prior.nutrition->>'origin'='ai_estimate' then prior.nutrition->>'source' end,
      case when payload->'nutrition'->>'origin'='ai_estimate' then payload->'nutrition'->>'source' end,
      case when prior.nutrient_source ~ '^(estimacion_ia|propuesta_ia)\.' then prior.nutrient_source end,
      case when payload->>'nutrient_source' ~ '^(estimacion_ia|propuesta_ia)\.' then payload->>'nutrient_source' end);
    source:=coalesce(ai_source,'catalogo_alimentos.v1');
    foreach key in array array['kcal','protein','carbs','fat','fiber','sodium','calcium','iron','potassium','magnesium','vitamin_c'] loop
      total:=0;
      for entry in select value from jsonb_array_elements(frozen_lines) loop
        if entry->'food'->'nutrients'->>key is null or coalesce(entry->>'native_quantity',entry->>'grams') is null then total:=null; exit; end if;
        total:=total+(entry->'food'->'nutrients'->>key)::numeric*coalesce(entry->>'native_quantity',entry->>'grams')::numeric/100;
      end loop;
      if key='carbs' and (select count(distinct coalesce(x->'food'->'composition'->>'carbohydrates','source_declared')) from jsonb_array_elements(frozen_lines) x where x->'food'<>'null'::jsonb)>1 then total:=null; end if;
      totals:=totals||jsonb_build_object(key,round(total,4));
      per_portion:=per_portion||jsonb_build_object(key,round(total/portions,4));
      per100:=per100||jsonb_build_object(key,round(total*100/final_weight,4));
    end loop;
    macros:=jsonb_build_object('kcal',per_portion->'kcal','protein_g',per_portion->'protein','carbs_g',per_portion->'carbs','fat_g',per_portion->'fat');
    if coalesce((macros->>'kcal')::numeric,0)>20000 or coalesce((macros->>'protein_g')::numeric,0)>2000 or coalesce((macros->>'carbs_g')::numeric,0)>2000 or coalesce((macros->>'fat_g')::numeric,0)>2000 then raise exception using errcode='22023',message='recipe_nutrition'; end if;
    if (macros->>'kcal')::numeric>0 and macros->>'protein_g' is not null and macros->>'carbs_g' is not null and macros->>'fat_g' is not null then
      derived_nutrition:=jsonb_build_object('origin',case when ai_source is null then 'declared' else 'ai_estimate' end,'source',source,'per_portion',macros);
    end if;
    card:=coalesce(payload->'card',jsonb_build_object('category','Almuerzo','prep_minutes',null,'cover_status','none','cover_alt',payload->>'title','cover_url',null));
    if exists(select 1 from jsonb_each(macros) where value<>'null'::jsonb) then
      card:=card||jsonb_build_object('macro_status','declared','macros',macros);
    else card:=card||jsonb_build_object('macro_status','unavailable','macros',null); end if;
    clean:=(clean-'nutrition')||jsonb_build_object('nutrient_source',source,'card',card);
    if derived_nutrition is not null then clean:=clean||jsonb_build_object('nutrition',derived_nutrition); end if;
    snapshot:=jsonb_build_object('lines',frozen_lines,'totals',totals,'per_portion',per_portion,'per_100g',case when final_weight is null then null else per100 end,
      'carbohydrates',case when (select count(distinct coalesce(x->'food'->'composition'->>'carbohydrates','source_declared')) from jsonb_array_elements(frozen_lines) x where x->'food'<>'null'::jsonb)>1 then 'mixed' when exists(select 1 from jsonb_array_elements(frozen_lines) x where x->'food' ? 'composition') then 'available' else 'source_declared' end,
      'ingredient_weight_g',case when unknown_weight then null else round(weight,4) end,'estimate_origin',ai_source is not null,'estimate_source',ai_source);
  end if;
  result:=public.save_recipe_draft_pre_catalog(clean); vid:=(result->'current'->>'id')::uuid;
  update public.recipe_versions set catalog_recipe=snapshot,final_weight_g=final_weight,cooking_minutes=cooking,
    nutrition=case when has_catalog then derived_nutrition when old_snapshot is not null and not(payload ? 'nutrition') then null else recipe_versions.nutrition end,
    nutrient_source=case when has_catalog then source else recipe_versions.nutrient_source end where id=vid;
  return public.recipe_professional_json(rid);
end; $$;
revoke all on function public.save_recipe_draft(jsonb) from public,anon;
grant execute on function public.save_recipe_draft(jsonb) to authenticated;
create or replace function public.shopping_list_json_before_vigencia(target_patient uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare vid uuid; ver int; pstart date; pend date; result jsonb;
begin
  select v.id,v.version,v.period_start,v.period_end into vid,ver,pstart,pend from public.meal_plans p join public.meal_plan_versions v on v.meal_plan_id=p.id and v.status='published' where p.patient_id=target_patient limit 1;
  with components as (
    select c from public.meal_plan_items i cross join lateral jsonb_array_elements(i.components) c where i.meal_plan_version_id=vid and i.components is not null
    union all
    select jsonb_build_object('kind','text','free_text',i.free_text,'portions',i.portions,'recipe_snapshot',j->'recipe','recipe_proposal',i.recipe_proposal)
    from public.meal_plan_items i cross join lateral (select public.meal_plan_item_json(i.id) j) x where i.meal_plan_version_id=vid and i.components is null
  ), expanded as (
    select c,coalesce(nullif(c->'recipe_snapshot','null'::jsonb),nullif(c->'recipe_proposal','null'::jsonb)) recipe from components
  ), raw as (
    select 'derived'::text kind,c->'food_snapshot'->>'name' name,
      round((c->>'quantity')::numeric*case when c->'measure'='null'::jsonb then 1 else (select (p->>'grams')::numeric from jsonb_array_elements(c->'food_snapshot'->'portions') p where p->>'name'=c->>'measure') end,2) quantity,coalesce(c->'food_snapshot'#>>'{composition,basis,unit}','g')::text unit
    from expanded where c->>'kind'='food'
    union all
    select 'derived',ingredient->>'name',round((ingredient->>'quantity')::numeric*coalesce((c->>'portions')::numeric,1)/(recipe->>'yield_portions')::numeric,2),ingredient->>'unit'
    from expanded cross join lateral jsonb_array_elements(recipe->'ingredients') ingredient where recipe is not null
    union all
    select 'text',c->>'free_text',null::numeric,null::text from expanded where recipe is null and c->>'kind'<>'food' and length(btrim(c->>'free_text'))>0
  ), grouped as (
    select kind,kind||':'||public.recipe_normalize_name(min(name))||case when kind='derived' then '|'||unit else '' end source_key,min(name) name,
      case when kind='derived' then round(sum(quantity),2) end quantity,unit,count(*)::int occurrences
    from raw group by kind,public.recipe_normalize_name(name),unit
    union all select 'manual','manual:'||m.id::text,m.name,m.quantity,m.unit,1 from public.shopping_manual_items m where m.patient_id=target_patient
  ) select coalesce(jsonb_agg(jsonb_build_object('id',case when kind='manual' then split_part(source_key,':',2) else source_key end,'kind',kind,'source_key',source_key,'name',name,'quantity',quantity,'unit',unit,'occurrences',occurrences,
    'checked',exists(select 1 from public.shopping_checks s where s.patient_id=target_patient and s.source_key=g.source_key and s.checked)) order by name,coalesce(unit,'')),'[]') into result from grouped g;
  return jsonb_build_object('plan_version',ver,'period_start',pstart,'period_end',pend,'items',result);
end; $$;
revoke all on function public.shopping_list_json_before_vigencia(uuid) from public,anon,authenticated;
create or replace function public.save_nutrition_exchange(request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare owner uuid:=public.recipe_assert_nutri(); identity uuid; expected bigint; old public.nutrition_exchanges; item jsonb; food public.food_catalog; frozen jsonb:='[]'; seen uuid[]:='{}'; food_id uuid; amount numeric; native_unit text; saved public.nutrition_exchanges;
begin
 if jsonb_typeof(request) is distinct from 'object' or not(request ?& array['id','expected_revision','name','reference','reviewed','items']) or (select count(*) from jsonb_object_keys(request))<>6 or request->'reviewed' is distinct from 'true'::jsonb or jsonb_typeof(request->'name')<>'string' or length(btrim(request->>'name')) not between 2 and 80 or jsonb_typeof(request->'reference')<>'string' or length(btrim(request->>'reference')) not between 3 and 500 or jsonb_typeof(request->'items')<>'array' or jsonb_array_length(request->'items') not between 2 and 5 or jsonb_typeof(request->'expected_revision')<>'number' then raise exception using errcode='22023',message='exchange_data';end if;
 if(request->>'expected_revision')::numeric<>trunc((request->>'expected_revision')::numeric)then raise exception using errcode='22023',message='exchange_revision';end if; identity:=(request->>'id')::uuid;expected:=(request->>'expected_revision')::bigint;if expected<0 then raise exception using errcode='22023',message='exchange_revision';end if;
 perform pg_advisory_xact_lock(hashtextextended(owner::text,82));perform pg_advisory_xact_lock(hashtextextended(identity::text,82));select * into old from public.nutrition_exchanges where id=identity for update;
 if old.id is not null and old.owner_id<>owner then raise exception using errcode='42501',message='exchange_owner';end if;
 if old.id is null and (select count(*) from public.nutrition_exchanges e where e.owner_id=owner)>=100 then raise exception using errcode='22023',message='exchange_limit';end if; if coalesce(old.revision,0)<>expected then raise exception using errcode='PT409',message='exchange_changed';end if;
 for item in select * from jsonb_array_elements(request->'items') loop
  if jsonb_typeof(item) is distinct from 'object' or not(item ?& array['food_id','food_revision']) or jsonb_typeof(item->'food_revision')<>'number' or not (((select count(*) from jsonb_object_keys(item))=3 and jsonb_typeof(item->'grams')='number') or ((select count(*) from jsonb_object_keys(item))=4 and jsonb_typeof(item->'quantity')='number' and item->>'unit' in ('g','ml'))) or exists(select 1 from jsonb_object_keys(item) k where k not in ('food_id','food_revision','grams','quantity','unit')) then raise exception using errcode='22023',message='exchange_item';end if;
  if(item->>'food_revision')::numeric<1 or(item->>'food_revision')::numeric<>trunc((item->>'food_revision')::numeric)then raise exception using errcode='22023',message='exchange_food_revision';end if;food_id:=(item->>'food_id')::uuid;amount:=coalesce(item->>'quantity',item->>'grams')::numeric;
  if food_id=any(seen) or amount<=0 or amount>100000 then raise exception using errcode='22023',message='exchange_item';end if;seen:=array_append(seen,food_id);
  select * into food from public.food_catalog f where f.id=food_id and(f.owner_id=owner or f.owner_id is null) for share;
  if not found then raise exception using errcode='42501',message='exchange_food_scope';end if;
  if food.revision<>(item->>'food_revision')::bigint then raise exception using errcode='PT409',message='exchange_food_changed';end if;
  native_unit:=coalesce(food.payload#>>'{composition,basis,unit}','g');
  if (item ? 'unit' and item->>'unit'<>native_unit) or (not(item ? 'unit') and native_unit<>'g') then raise exception using errcode='22023',message='exchange_native_unit'; end if;
  frozen:=frozen||jsonb_build_array(jsonb_build_object('quantity',amount,'unit',native_unit,'grams',case when native_unit='g' then amount else null end,'food',food.payload||jsonb_build_object('id',food.id,'revision',food.revision,'owner_id',food.owner_id,'updated_at',food.updated_at)));
 end loop;
 insert into public.nutrition_exchanges(id,owner_id,revision,payload) values(identity,owner,expected+1,jsonb_build_object('name',btrim(request->>'name'),'reference',btrim(request->>'reference'),'items',frozen)) on conflict(id) do update set revision=excluded.revision,payload=excluded.payload,updated_at=now() returning * into saved;
 return saved.payload||jsonb_build_object('id',saved.id,'owner_id',saved.owner_id,'revision',saved.revision,'updated_at',saved.updated_at);
end $$;
revoke all on function public.save_nutrition_exchange(jsonb) from public,anon;
grant execute on function public.save_nutrition_exchange(jsonb) to authenticated;
commit;
